BEGIN;
CREATE TABLE IF NOT EXISTS public.site_why (
 id text PRIMARY KEY DEFAULT 'main' CHECK (id = 'main'),
 cards jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(cards) = 'array' AND jsonb_array_length(cards) <= 12),
 media_cleanup_paths jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(media_cleanup_paths) = 'array'),
 revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
 updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.site_why ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.site_why FROM anon, authenticated;
GRANT SELECT ON public.site_why TO anon, authenticated;
GRANT ALL ON public.site_why TO service_role;
CREATE POLICY "Why is public" ON public.site_why FOR SELECT TO anon, authenticated USING (true);
INSERT INTO public.site_why (id, cards) VALUES ('main', '[{"id":"reliability","sortOrder":10,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" viewBox=\"0 0 24 24\" color=\"#ffffff\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"><path d=\"m15.477 12.89l1.515 8.526a.5.5 0 0 1-.81.47l-3.58-2.687a1 1 0 0 0-1.197 0l-3.586 2.686a.5.5 0 0 1-.81-.469l1.514-8.526\"/><circle cx=\"12\" cy=\"8\" r=\"6\"/></g></svg>","iconFilename":"logo.svg","iconPath":null,"title":"Надежность\nи опыт","points":["Многолетний успешный опыт работы с государственными и коммерческими объектами","Обслуживаем более 300 объектов в Санкт-Петербурге и Ленинградской области"]},{"id":"team","sortOrder":20,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" viewBox=\"0 0 24 24\" color=\"#ffffff\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3.128a4 4 0 0 1 0 7.744M22 21v-2a4 4 0 0 0-3-3.87\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/></g></svg>","iconFilename":"logo.svg","iconPath":null,"title":"Профессионализм\nкоманды","points":["Опытные специалисты в области инженерных систем","Постоянное развитие профессиональных навыков"]},{"id":"approach","sortOrder":30,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" viewBox=\"0 0 24 24\" color=\"#ffffff\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"><path d=\"M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></g></svg>","iconFilename":"logo.svg","iconPath":null,"title":"Индивидуальный\nподход","points":["Учитываем особенности каждого объекта","Подбираем состав работ под ваши задачи"]},{"id":"control","sortOrder":40,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" viewBox=\"0 0 24 24\" color=\"#ffffff\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"><path d=\"M2.062 12.348a1 1 0 0 1 0-.696a10.75 10.75 0 0 1 19.876 0a1 1 0 0 1 0 .696a10.75 10.75 0 0 1-19.876 0\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></g></svg>","iconFilename":"logo.svg","iconPath":null,"title":"Прозрачность\nи контроль","points":["Согласовываем работы, сроки и стоимость","Предоставляем информацию о выполненных работах"]},{"id":"service","sortOrder":50,"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" viewBox=\"0 0 24 24\" color=\"#ffffff\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 6v6l4 2\"/></g></svg>","iconFilename":"logo.svg","iconPath":null,"title":"Оперативность\nи сервис","points":["Оперативно отвечаем на обращения","Помогаем решать вопросы эксплуатации"]}]'::jsonb) ON CONFLICT (id) DO NOTHING;
NOTIFY pgrst, 'reload schema';
COMMIT;
